    int q = a / b;
    int r = a % b;
    if (r != 0 && ((r < 0) != (b < 0))) --q;
    return q;
}
__global__ void conv_transpose2d_kernel(
    const float* __restrict__ x_ptr,
    const float* __restrict__ w_ptr,
    const float* __restrict__ bias_ptr,
    float* __restrict__ out_ptr,
    int N, int C_in, int H_in, int W_in,
    int C_out, int H_out, int W_out,
    int KH, int KW,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int groups, int in_channels_per_group, int out_channels_per_group,
    bool has_bias,
    int SH, int SW)
{
    // Decode (n, g) from blockIdx.z. Each CTA now handles an entire group,
    // so the cached input tile *and* the cached weight tile are reused across
    // all out_channels_per_group output channels instead of being reloaded
    // from global memory redundantly for every output channel (as the
    // previous per-(n, oc) CTA mapping did).
    int ng_idx = blockIdx.z;
    int n = ng_idx / groups;
    int g = ng_idx % groups;
    int ic_start = g * in_channels_per_group;
    int oc_start = g * out_channels_per_group;
    // CuTe tensors for global memory access
    Tensor gX = make_tensor(make_gmem_ptr(x_ptr),
                             make_shape(N, C_in, H_in, W_in),
                             make_stride(C_in * H_in * W_in, H_in * W_in, W_in, 1));
    Tensor gW = make_tensor(make_gmem_ptr(w_ptr),
                             make_shape(C_in, out_channels_per_group, KH, KW),
                             make_stride(out_channels_per_group * KH * KW, KH * KW, KW, 1));
    Tensor gOut = make_tensor(make_gmem_ptr(out_ptr),
                               make_shape(N, C_out, H_out, W_out),
                               make_stride(C_out * H_out * W_out, H_out * W_out, W_out, 1));
    extern __shared__ float smem[];
    // Shared memory layout: [weight tile for the whole group][input tile for the whole group]
    int total_w = in_channels_per_group * out_channels_per_group * KH * KW;
    float* smem_w = smem;
    float* smem_x = smem + total_w;
    int tid = threadIdx.y * blockDim.x + threadIdx.x;
    int nthreads = blockDim.x * blockDim.y;
    for (int idx = tid; idx < total_w; idx += nthreads) {
        int kw = idx % KW;
        int tmp = idx / KW;
        int kh = tmp % KH;
        tmp = tmp / KH;
        int oc_local = tmp % out_channels_per_group;
        int ic_local = tmp / out_channels_per_group;
        smem_w[idx] = gW(ic_start + ic_local, oc_local, kh, kw);
    }
    // Compute base input coordinates covered by this CTA's output tile.
    int oh_start = blockIdx.y * TILE_H;
    int ow_start = blockIdx.x * TILE_W;
    int num_min_h = oh_start + pad_h - (KH - 1) * dil_h;
    int ih_lo = floor_div(num_min_h, stride_h);
    int num_min_w = ow_start + pad_w - (KW - 1) * dil_w;
    int iw_lo = floor_div(num_min_w, stride_w);
    int SWP = SW + ((SW & 31) == 0 ? 1 : 0);
    int total_x = in_channels_per_group * SH * SW;
    for (int idx = tid; idx < total_x; idx += nthreads) {
        int iw_local = idx % SW;
        int tmp2 = idx / SW;
        int ih_local = tmp2 % SH;
        int ic_local = tmp2 / SH;
        int ih = ih_lo + ih_local;
        int iw = iw_lo + iw_local;
        float v = 0.0f;
        if (ih >= 0 && ih < H_in && iw >= 0 && iw < W_in) {
            v = gX(n, ic_start + ic_local, ih, iw);
        }
        int pad_idx = ic_local * SH * SWP + ih_local * SWP + iw_local;
        smem_x[pad_idx] = v;
    }
    __syncthreads();
    const int REG_TILE_H = TILE_H / BLOCK_DIM_Y;
    const int REG_TILE_W = TILE_W / BLOCK_DIM_X;
    const int MAX_K = 32;
    int ih_local_arr[REG_TILE_H][MAX_K];
    bool valid_h_arr[REG_TILE_H][MAX_K];
    int oh_arr[REG_TILE_H];
    #pragma unroll
    for (int dy = 0; dy < REG_TILE_H; ++dy) {
        int oh = oh_start + threadIdx.y + dy * BLOCK_DIM_Y;
        oh_arr[dy] = oh;
        for (int kh = 0; kh < KH; ++kh) {
            int t_h = oh + pad_h - kh * dil_h;
            bool ok = (oh < H_out) && (t_h % stride_h == 0);
            int ih = ok ? (t_h / stride_h) : 0;
            int ih_local = ih - ih_lo;
            ok = ok && (ih_local >= 0 && ih_local < SH);
            ih_local_arr[dy][kh] = ih_local;
            valid_h_arr[dy][kh] = ok;
        }
    }
    int iw_local_arr[REG_TILE_W][MAX_K];
    bool valid_w_arr[REG_TILE_W][MAX_K];
    int ow_arr[REG_TILE_W];
    #pragma unroll
    for (int dx = 0; dx < REG_TILE_W; ++dx) {
        int ow = ow_start + threadIdx.x + dx * BLOCK_DIM_X;
        ow_arr[dx] = ow;
        for (int kw = 0; kw < KW; ++kw) {
            int t_w = ow + pad_w - kw * dil_w;
            bool ok = (ow < W_out) && (t_w % stride_w == 0);
            int iw = ok ? (t_w / stride_w) : 0;
            int iw_local = iw - iw_lo;
            ok = ok && (iw_local >= 0 && iw_local < SW);
            iw_local_arr[dx][kw] = iw_local;
            valid_w_arr[dx][kw] = ok;
        }
    }
    // Iterate over all output channels belonging to this group, reusing the
    // cached input tile *and* the cached weight tile across all of them.
    // This removes the redundant global-memory reload of the (large) input
    // tile that previously happened once per output channel.
    // Register-block over multiple output channels within the group so that
    // the shared-memory input value loaded per (kh, kw, ic, dy, dx) is reused
    // across OC_TILE output channels instead of being re-read from shared
    // memory once per output channel. This reduces shared-memory traffic by
    // roughly a factor of OC_TILE while keeping the same weight-tile reuse.
    const int OC_TILE = 4;
    for (int oc_local0 = 0; oc_local0 < out_channels_per_group; oc_local0 += OC_TILE) {
        int oc_cnt = out_channels_per_group - oc_local0;
        if (oc_cnt > OC_TILE) oc_cnt = OC_TILE;
        float acc[OC_TILE][REG_TILE_H][REG_TILE_W];
        #pragma unroll
        for (int t = 0; t < OC_TILE; ++t) {
            #pragma unroll
            for (int dy = 0; dy < REG_TILE_H; ++dy) {
                #pragma unroll
                for (int dx = 0; dx < REG_TILE_W; ++dx) {
                    acc[t][dy][dx] = 0.0f;
                }
            }
        }
        for (int kh = 0; kh < KH; ++kh) {
            for (int kw = 0; kw < KW; ++kw) {
                int w_off = kh * KW + kw;
                #pragma unroll 4
                for (int ic_local = 0; ic_local < in_channels_per_group; ++ic_local) {
                    float wv[OC_TILE];
                    #pragma unroll
                    for (int t = 0; t < OC_TILE; ++t) {
                        wv[t] = (t < oc_cnt)
                            ? smem_w[(ic_local * out_channels_per_group + (oc_local0 + t)) * KH * KW + w_off]
                            : 0.0f;
                    }
                    const float* smx_ic = smem_x + ic_local * SH * SWP;
                    #pragma unroll
                    for (int dy = 0; dy < REG_TILE_H; ++dy) {
                        if (!valid_h_arr[dy][kh]) continue;
                        int x_row_off = ih_local_arr[dy][kh] * SWP;
                        #pragma unroll
                        for (int dx = 0; dx < REG_TILE_W; ++dx) {
                            if (!valid_w_arr[dx][kw]) continue;
                            float xv = smx_ic[x_row_off + iw_local_arr[dx][kw]];
                            #pragma unroll
                            for (int t = 0; t < OC_TILE; ++t) {
                                acc[t][dy][dx] += xv * wv[t];
                            }
                        }
                    }
                }
            }
        }
        #pragma unroll
        for (int t = 0; t < OC_TILE; ++t) {
            if (t >= oc_cnt) continue;
            int oc = oc_start + oc_local0 + t;
            #pragma unroll
            for (int dy = 0; dy < REG_TILE_H; ++dy) {
                int oh = oh_arr[dy];
                if (oh >= H_out) continue;
                #pragma unroll
                for (int dx = 0; dx < REG_TILE_W; ++dx) {
                    int ow = ow_arr[dx];
                    if (ow >= W_out) continue;
                    float v = acc[t][dy][dx];
                    if (has_bias) {
                        v += bias_ptr[oc];
                    }
                    gOut(n, oc, oh, ow) = v;
                }
            }
        }
    }
}
torch::Tensor cute_conv_transpose2d(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    bool has_bias,
    int64_t stride_h, int64_t stride_w,
    int64_t pad_h, int64_t pad_w,
    int64_t dil_h, int64_t dil_w,
    int64_t groups)
{
    TORCH_CHECK(x.is_cuda() && weight.is_cuda(), "tensors must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat && weight.scalar_type() == at::kFloat,
                "Expect float32 tensors");
    TORCH_CHECK(x.dim() == 4, "x must be 4D (N,C,H,W)");
    TORCH_CHECK(weight.dim() == 4, "weight must be 4D (C_in, C_out/groups, KH, KW)");
    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();
    int N = (int)x_c.size(0);
    int C_in = (int)x_c.size(1);
    int H_in = (int)x_c.size(2);
    int W_in = (int)x_c.size(3);
    int out_channels_per_group = (int)w_c.size(1);
    int KH = (int)w_c.size(2);
    int KW = (int)w_c.size(3);
    int C_out = out_channels_per_group * (int)groups;
    int in_channels_per_group = C_in / (int)groups;
    int H_out = (H_in - 1) * (int)stride_h - 2 * (int)pad_h + (int)dil_h * (KH - 1) + 1;
    int W_out = (W_in - 1) * (int)stride_w - 2 * (int)pad_w + (int)dil_w * (KW - 1) + 1;
    auto out = torch::empty({N, C_out, H_out, W_out}, x_c.options());
    const float* bias_ptr = nullptr;
    torch::Tensor bias_c;
    if (has_bias) {
        bias_c = bias.contiguous();
        bias_ptr = bias_c.data_ptr<float>();
    }
    dim3 block(BLOCK_DIM_X, BLOCK_DIM_Y);
    dim3 grid((W_out + TILE_W - 1) / TILE_W,
              (H_out + TILE_H - 1) / TILE_H,
              N * (int)groups);
    // Size of shared-memory input tile that covers the receptive field of one
    // CTA's output tile, so all threads in the CTA can reuse cached input
    // values instead of re-reading global memory redundantly. Now this tile
    // (and the full per-group weight tile) is loaded exactly once per CTA and
    // reused across all out_channels_per_group output channels of the group.
    int SH = ((TILE_H - 1) + (KH - 1) * (int)dil_h) / (int)stride_h + 2;
    int SW = ((TILE_W - 1) + (KW - 1) * (int)dil_w) / (int)stride_w + 2;
    int SWP = SW + ((SW & 31) == 0 ? 1 : 0);
    size_t smem_bytes = (size_t)in_channels_per_group * out_channels_per_group * KH * KW * sizeof(float)
                       + (size_t)in_channels_per_group * SH * SWP * sizeof(float);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    if (smem_bytes > 48 * 1024) {
        cudaFuncSetAttribute(conv_transpose2d_kernel,
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             (int)smem_bytes);
    }
    conv_transpose2d_kernel<<<grid, block, smem_bytes, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        bias_ptr,
        out.data_ptr<float>(),
        N, C_in, H_in, W_in,
        C_out, H_out, W_out,
        KH, KW,
        (int)stride_h, (int)stride_w,
        (int)pad_h, (int)pad_w,
        (int)dil_h, (int)dil_w,
        (int)groups, in_channels_per_group, out_channels_per_group,
        has_bias, SH, SW);
    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE conv_transpose2d launch failed");
    return out;
}
